local config = {
  ui_story_32270401_1_dialog_content = "Paquete para ti, Rachel—",
  ui_story_32270401_2_dialog_content = "Tú... viniste mucho antes de lo que esperaba.",
  ui_story_32270401_3_dialog_content = "(¿Eh? ¿Lo imaginé, o Rachel ocultó algo justo ahora?)",
  ui_story_32270401_4_dialog_content = "Vaya, ¿qué son todas estas partes? ¿Estás...? Oh, lo siento, no quise entrometerme...",
  ui_story_32270401_5_dialog_content = "Está bien, no hay nada que ocultarte aquí, en su mayoría.",
  ui_story_32270401_6_dialog_content = "De todos modos, te traje tu paquete. ¿Eh? ¿Es esto algún tipo de medicina?",
  ui_story_32270401_7_dialog_content = "No estás enfermo, ¿verdad?",
  ui_story_32270401_8_dialog_content = "No te preocupes, no lo estoy. Mira más de cerca.",
  ui_story_32270401_9_dialog_content = "\"¿Tabletas de nutrientes 30 en 1\"? Urgh, huelen peor que la cocina de Vice...",
  ui_story_32270401_10_dialog_content = "El olor no es importante. Estas tabletas de nutrientes son realmente muy útiles.",
  ui_story_32270401_11_dialog_content = "Compuesto por treinta ingredientes diferentes, una tableta contiene el valor nutricional completo de una cena saludable y equilibrada.",
  ui_story_32270401_12_dialog_content = "Me ahorran mucho tiempo, especialmente cuando estoy muy ocupado. Acabo de terminar mi último suministro, y la Unión de Mensajería entregó otro de inmediato. Son tan confiables como siempre—",
  ui_story_32270401_13_dialog_content = "¡Espera! ¿Has... Has estado comiendo solo esto en los últimos días? ¿No has comido comida real?",
  ui_story_32270401_14_dialog_content = "Nada en absoluto. Con el valor funcional y nutricional de estas tabletas, no hay necesidad de ingerir ninguna sustancia adicional.",
  ui_story_32270401_15_dialog_content = "\"Ingiere alimento\", dice ella... ¡No puedes simplemente saltarte las comidas así, Rachel!",
  ui_story_32270401_16_dialog_content = "La comida tiene muchos otros beneficios además de la nutrición, ya sabes.",
  ui_story_32270401_17_dialog_content = "¿Por ejemplo?",
  ui_story_32270401_18_dialog_content = "B-Bueno, comer comida deliciosa puede ser realmente agradable y relajante, especialmente cuando comes con amigos...",
  ui_story_32270401_19_dialog_content = "Entiendo tu punto de vista.",
  ui_story_32270401_20_dialog_content = "(¡Seguro que no parece ser así!)",
  ui_story_32270401_21_dialog_content = "... Ahora que lo pienso, han pasado días desde la última vez que te vi en la cafetería.",
  ui_story_32270401_22_dialog_content = "Y aún así no noté nada malo... Eso es un fallo de mi parte como tu anfitrión.",
  ui_story_32270401_23_dialog_content = "Ya es bastante difícil para ti tomarte un tiempo libre, e incluso elegiste pasar tus vacaciones a bordo del Colossus...",
  ui_story_32270401_24_dialog_content = "No hay necesidad de sentirse tan desanimado por esto.",
  ui_story_32270401_25_dialog_content = "Ah, lo siento. No te estaba culpando ni nada, solo quería decir...",
  ui_story_32270401_26_dialog_content = "Eres un buen anfitrión, y he estado pasando un tiempo maravilloso aquí en el Colossus.",
  ui_story_32270401_27_dialog_content = "¿D-De veras?",
  ui_story_32270401_28_dialog_content = "... Qué rápida respuesta.",
  ui_story_32270401_29_dialog_content = "¡Eso lo resuelve! ¡Te invitaré a una buena y caliente comida en Umbraton esta noche!",
  ui_story_32270401_30_dialog_content = "Eso no será necesario. Todavía tengo una serie de importantes problemas mecánicos que resolver, y—",
  ui_story_32270401_31_dialog_content = "¡No te preocupes, estará bien! Dividir pelos solo complicará las cosas, así que ¡hagámoslo!",
  ui_story_32270401_32_dialog_content = "¡Esta noche a las siete en Umbraton! ¡Estar allí!",
  ui_story_32270401_33_dialog_content = "...",
  ui_story_32270401_34_dialog_content = "(Estoy un poco nervioso... ¿Fui demasiado insistente cuando invité a Rachel a cenar esta noche? ¿Y si no viene?)",
  ui_story_32270401_35_dialog_content = "<color=#e8d9bb>Un reloj de abuelo en la esquina del restaurante da las siete en punto.</color>",
  ui_story_32270401_36_dialog_content = "Lo siento por el retraso, Caelestita Uno.",
  ui_story_32270401_37_dialog_content = "Rachel! ¡Apareciste exactamente a las siete en punto!",
  ui_story_32270401_38_dialog_content = "Por supuesto. Nunca deberías llegar tarde a una misión.",
  ui_story_32270401_39_dialog_content = "¿Una misión?",
  ui_story_32270401_40_dialog_content = "... ¡Es solo una forma de hablar! Definitivamente no estoy tratando esta cena como una misión o algo así.",
  ui_story_32270401_41_dialog_content = "Sin embargo, tengo un asunto urgente que atender durante la cena de esta noche.",
  ui_story_32270401_42_dialog_content = "Ya veo... Lamento haberte interrumpido cuando estás tan ocupado...",
  ui_story_32270401_43_dialog_content = "Aquí está tu limonada, señorita.",
  ui_story_32270401_44_dialog_content = "... Pensé que podrías tener sed, así que pedí eso para ti.",
  ui_story_32270401_45_dialog_content = "Gracias.",
  ui_story_32270401_46_dialog_content = "(¡Guau! ¡Se lo bebió todo de un trago!)",
  ui_story_32270401_47_dialog_content = "Así como algo de pan y mantequilla de cortesía.",
  ui_story_32270401_48_dialog_content = "Gracias.",
  ui_story_32270401_49_dialog_content = "(¡Ella también terminó el pan de un solo bocado! ¡Ni siquiera queda un rastro de mantequilla en el plato!)",
  ui_story_32270401_50_dialog_content = "(Y ahora ella está sentada erguida con las manos en su regazo, como si nada hubiera pasado...)",
  ui_story_32270401_51_dialog_content = "Eh... Rachel?",
  ui_story_32270401_52_dialog_content = "¿Sí? ¿Qué pasa, Caelestita Uno?",
  ui_story_32270401_53_dialog_content = "No estamos en una base militar, lo sabes, ¿verdad?",
  ui_story_32270401_54_dialog_content = "No estás contra reloj aquí, así que tómate tu tiempo y disfruta de la comida, ¿de acuerdo?",
  ui_story_32270401_55_dialog_content = "¿Eh? No entiendo. ¿Por qué tomaría mi tiempo cuando puedo terminar mi comida en solo unos segundos?",
  ui_story_32270401_56_dialog_content = "Porque te permite apreciar realmente el sabor de la comida.",
  ui_story_32270401_57_dialog_content = "Algo tan insignificante como el sabor no debería tener prioridad sobre la eficiencia—",
  ui_story_32270401_58_dialog_content = "... Lo siento, quizás \"insignificante\" es un poco duro. Lo que quise decir es—",
  ui_story_32270401_59_dialog_content = "... Está bien, entiendo. Dijiste que estás en una misión, después de todo... Lo siento.",
  ui_story_32270401_60_dialog_content = "Probablemente tenga demasiado tiempo libre en mis manos, por lo que es fácil para mí hablar de cosas así...",
  ui_story_32270401_61_dialog_content = "Jaja... ¿Por qué no echamos un vistazo al menú? Todavía no hemos pedido ningún plato principal.",
  ui_story_32270401_62_dialog_content = "Mi misión no es lo que piensas, PlayerName. La-La verdad es...",
  ui_story_32270401_63_dialog_content = "¡Yo... Yo quiero darte algo! ¡Aquí—",
  ui_story_32270401_64_dialog_content = "¡Miau!",
  ui_story_32270401_65_dialog_content = "Wow, ¿de dónde salió ese gato?",
  ui_story_32270401_66_dialog_content = "¡Miau, miau!",
  ui_story_32270401_67_dialog_content = "¡Oh no... No dejes que se escape!",
  ui_story_32270401_68_dialog_content = "¿Ah?",
  ui_story_32270401_69_dialog_content = "¡Tras ese gato! Robó tu... quiero decir, robó <color=#FFB400>algo muy importante</color>!",
  ui_story_32270401_70_dialog_content = "Por ahí!",
  ui_story_32270401_71_dialog_content = "¡Espera ahí mismo, gato!",
  ui_story_32270401_72_dialog_content = "¡Miau!",
  ui_story_32270401_73_dialog_content = "¡Está subiendo por la pared de nuevo! Urgh, no somos rival para las habilidades de escalada de un gato...",
  ui_story_32270401_74_dialog_content = "Perseguirlo así no funcionará... Es casi imposible seguir el ritmo de un gato en la ciudad por la noche. Necesitamos idear una estrategia.",
  ui_story_32270401_75_dialog_content = "Una estrategia, ¿eh? Déjame pensar... Podría intentar sentir su ubicación.",
  ui_story_32270401_76_dialog_content = "Perfecto. Dime su ubicación y haré que mis Cazadores de Águilas lo persigan hasta un callejón sin salida. Una vez que esté atrapado...",
  ui_story_32270401_77_dialog_content = "¡Saltaré y lo agarraré!",
  ui_story_32270401_78_dialog_content = "Captas rápido, Caelestite One. ¡Comencemos la operación!",
  ui_story_32270401_79_dialog_content = "¡En el techo!",
  ui_story_32270401_80_dialog_content = "¡Miau!",
  ui_story_32270401_81_dialog_content = "¡Saltó sobre la pared de allí!",
  ui_story_32270401_82_dialog_content = "¡Miau!",
  ui_story_32270401_83_dialog_content = "Miau... ¿Miau? Miau, miau...",
  ui_story_32270401_84_dialog_content = "¡Miau, miau!",
  ui_story_32270401_85_dialog_content = "¡No te vas a escapar!",
  ui_story_32270401_86_dialog_content = "¡Miau! Miau, miau, miau!",
  ui_story_32270401_87_dialog_content = "Dámelo a mí, Caelestite Uno.",
  ui_story_32270401_88_dialog_content = "Lo siento si te asustamos, pequeño gatito.",
  ui_story_32270401_89_dialog_content = "(Su voz y expresión se volvieron de repente muy suaves... Completamente olvidé este lado de ella.)",
  ui_story_32270401_90_dialog_content = "¿Qué tal algunos rasguños?",
  ui_story_32270401_91_dialog_content = "¡Miau! Ronroneo...",
  ui_story_32270401_92_dialog_content = "(¡El gato bajó completamente su guardia!)",
  ui_story_32270401_93_dialog_content = "Ahora, sé un buen gatito y quédate quieto... ¡Ahí!",
  ui_story_32270401_94_dialog_content = "Buen trabajo, Rachel! ¿Entonces qué es exactamente esta \"cosa muy importante\"?",
  ui_story_32270401_95_dialog_content = "Yo-Yo es...",
  ui_story_32270401_96_dialog_content = "<color=#e8d9bb>*gruñido estomacal*</color>",
  ui_story_32270401_97_dialog_content = "!",
  ui_story_32270401_98_dialog_content = "Ahh, ahora que hemos terminado de perseguir a ese gato, me doy cuenta de lo hambriento que estoy...",
  ui_story_32270401_99_dialog_content = "Lo siento, todo es mi culpa. No pudimos pedir nuestra comida antes...",
  ui_story_32270401_100_dialog_content = "Espera, creo que todavía tengo algo... ¡Ajá, aquí está! ¡Un sándwich de queso!",
  ui_story_32270401_101_dialog_content = "El pan está un poco aplastado, pero... ¡Sí! ¡Todavía sabe bien!",
  ui_story_32270401_102_dialog_content = "¡Miau! Miau, miau!",
  ui_story_32270401_103_dialog_content = "¿También tienes hambre, pequeño? Aquí, podemos compartir.",
  ui_story_32270401_104_dialog_content = "¡Miau, miau!",
  ui_story_32270401_105_dialog_content = "Parece que realmente le gustas, ¿eh? Ven aquí, gatito, tengo tu pedazo justo aquí.",
  ui_story_32270401_106_dialog_content = "Sé que es lindo y todo, pero no le des todo tu sándwich, Rachel. ¡No quedará nada para ti!",
  ui_story_32270401_107_dialog_content = "Yo-Yo no tenía la intención de... De todos modos, vamos a comer—",
  ui_story_32270401_108_dialog_content = "... ¡Es delicioso!",
  ui_story_32270401_109_dialog_content = "¡Miau! ¡Miau!",
  ui_story_32270401_110_dialog_content = "¿Qué, quieres un poco más? Para ser pequeño, tienes un gran apetito. ¿Es esto suficiente para ti?",
  ui_story_32270401_111_dialog_content = "Jejeje...",
  ui_story_32270401_112_dialog_content = "¿Qué es tan gracioso?",
  ui_story_32270401_113_dialog_content = "Recuerdo que alguien me dijo que no alimentara al gato, y ahora él le está dando toda su comida.",
  ui_story_32270401_114_dialog_content = "E-Eso es solo porque lo asustamos tanto justo ahora! Además, todavía tengo mucho! ¿Ves?",
  ui_story_32270401_115_dialog_content = "... ¿Siempre llevas tanta comida seca contigo?",
  ui_story_32270401_116_dialog_content = "No tienes idea de lo que he pasado, Rachel...",
  ui_story_32270401_117_dialog_content = "Je...",
  ui_story_32270401_118_dialog_content = "(Ella está riendo de nuevo... Siento que ha reído más veces esta noche que nunca antes.)",
  ui_story_32270401_119_dialog_content = "Yo... creo que ahora entiendo. Cuando las personas tienen algo delicioso para comer, se toman su tiempo porque no quieren que la experiencia termine.",
  ui_story_32270401_120_dialog_content = "Y solo cuando están felices pueden apreciar realmente el sabor de la comida.",
  ui_story_32270401_121_dialog_content = "En este momento, el sándwich en mi mano sabe especialmente delicioso.",
  ui_story_32270401_122_dialog_content = "(No puedo creer que haya dicho todo eso con una cara tan feliz. Es totalmente fuera de su carácter...)",
  ui_story_32270401_123_dialog_content = "¿Hmm? ¿Por qué tu cara está tan roja? ¿Podría ser que no te agotaste por todo ese correteo?",
  ui_story_32270401_124_dialog_content = "¡N-N-No es nada! Jajaja... No puede ser tan bueno, ¿verdad? Después de todo, ¡es solo un sándwich!",
  ui_story_32270401_125_dialog_content = "No comas demasiado, ¿de acuerdo? Todavía podemos volver al restaurante y pedir nuestra comida.",
  ui_story_32270401_126_dialog_content = "No es necesario. Ya he tenido la cena más deliciosa, todo gracias a mi maravilloso anfitrión.",
  ui_story_32270401_127_dialog_content = "Aquí, PlayerName... Esta medalla es para ti.",
  ui_story_32270401_128_dialog_content = "\"¿El Mejor Anfitrión del Mundo\"? Es hermoso... Espera, ¿me estás dando esto a mí?",
  ui_story_32270401_129_dialog_content = "Sí. Espero que no te importe, pero lo hice yo mismo.",
  ui_story_32270401_130_dialog_content = "¡Ah! ¡Así que esto es lo que estabas escondiendo cuando fui a tu habitación más temprano hoy! También es la \"cosa muy importante\" que nuestro pequeño amigo intentó robar...",
  ui_story_32270401_131_dialog_content = "¡Miau!",
  ui_story_32270401_132_dialog_content = "Así es... Cuando me invitaste a cenar, pensé que era la ocasión perfecta para darte esto.",
  ui_story_32270401_133_dialog_content = "Cada día que he pasado en Soroz es tan tranquilo y divertido.",
  ui_story_32270401_134_dialog_content = "Experimento un disfrute como nunca antes había sentido, y todo es gracias a ti, PlayerName.",
  ui_story_32270401_135_dialog_content = "Sin un anfitrión increíble como tú, nunca habría tenido unas vacaciones tan maravillosas—",
  ui_story_32270401_136_dialog_content = "... Tampoco habría experimentado la verdadera alegría de la comida por primera vez en mi vida.",
  ui_story_32270401_137_dialog_content = "Gracias. Siempre recordaré cada momento de mi tiempo a bordo del Colossus.",
  ui_story_32270401_138_dialog_content = "¡Rachel!",
  ui_story_32270401_139_dialog_content = "¡Bien, entonces está decidido! ¡A partir de mañana, el anfitrión más grande del mundo te mostrará todas las cosas increíbles que Astra tiene para ofrecer!",
  ui_story_32270401_140_dialog_content = "¿E-Eh?",
  ui_story_32270401_141_dialog_content = "¡Y comenzaremos con las carreras del Desierto Rediesel! Agárrate fuerte—",
  ui_story_32270401_142_dialog_content = "¡Espera, solo cálmate un poco!",
  ui_story_32270601_1_dialog_content = "<color=#e8d9bb>Chapoteo... Chapoteo...</color>",
  ui_story_32270601_2_dialog_content = "Esto es raro...",
  ui_story_32270601_3_dialog_content = "¿Por qué la playa aquí no es animada en absoluto?",
  ui_story_32270601_4_dialog_content = "¿No debería la playa estar llena de gente en esta época del año...?",
  ui_story_32270601_5_dialog_content = "(¿Podría ser... malinterpreté las intenciones de Reinhardt?)",
  ui_story_32270601_6_dialog_content = "Ahora tengo una \"misión\" que quiero confiarte, PlayerName.",
  ui_story_32270601_7_dialog_content = "Por supuesto, hay una recompensa.",
  ui_story_32270601_8_dialog_content = "¿No somos amigos...? ¿Por qué tan formal de repente, me está poniendo un poco nervioso...",
  ui_story_32270601_9_dialog_content = "¡Jaja! No es una misión particularmente difícil, pero...",
  ui_story_32270601_10_dialog_content = "Necesito que acompañes a Rachel a la playa y te asegures de que se divierta. Eso es todo. Cuento contigo.",
  ui_story_32270601_11_dialog_content = "Caelestita Uno... Ah, no, debería llamarte PlayerName.",
  ui_story_32270601_12_dialog_content = "Gracias por tomarte el tiempo para venir y unirte a mí en esta búsqueda.",
  ui_story_32270601_13_dialog_content = "¿De... De verdad una misión...?",
  ui_story_32270601_14_dialog_content = "Pero el atuendo de Rachel hoy... ¿no parece que esté en una misión?",
  ui_story_32270601_15_dialog_content = "Esto... Fui a Umbraton específicamente para infiltrarme en la playa.",
  ui_story_32270601_16_dialog_content = "El alto Presidente del Gremio eligió personalmente un traje de baño para mí.",
  ui_story_32270601_17_dialog_content = "Ella dijo que es el último artículo de temporada, garantizado para mezclarse perfectamente con el ambiente de la playa, pero...",
  ui_story_32270601_18_dialog_content = "¿Es esta la primera vez que te das cuenta... de lo vergonzoso que es llevar un traje de baño?",
  ui_story_32270601_19_dialog_content = "(El alto presidente del gremio, ¿podría ser la Señora Sheol...)",
  ui_story_32270601_20_dialog_content = "(Este traje de baño... Definitivamente es el estilo que ella recomendaría...)",
  ui_story_32270601_21_dialog_content = "No te avergüences, te ves muy bien en eso, Rachel.",
  ui_story_32270601_22_dialog_content = "¡No hay traje de baño en esta playa más hermoso que el tuyo!",
  ui_story_32270601_23_dialog_content = "No hay... nadie más aquí, ¿verdad...",
  ui_story_32270601_24_dialog_content = "*Tose* En realidad, me preguntaba por qué no hay nadie más aquí...",
  ui_story_32270601_25_dialog_content = "Hmm, parece ser una zona desierta.",
  ui_story_32270601_26_dialog_content = "¡¿N-Tierra de nadie?!",
  ui_story_32270601_27_dialog_content = "También acabo de usar un dron para explorar el terreno costero y llegué a esta conclusión.",
  ui_story_32270601_28_dialog_content = "El Gran Mariscal me envió específicamente de vacaciones a este lugar, probablemente aún espera que pueda producir un informe de encuesta.",
  ui_story_32270601_29_dialog_content = "Las palabras del Gran Mariscal...",
  ui_story_32270601_30_dialog_content = "¡No, no, no, definitivamente ella quiere que disfrutes tus vacaciones, por eso te trajo aquí!",
  ui_story_32270601_31_dialog_content = "¿En serio?",
  ui_story_32270601_32_dialog_content = "Si realmente es unas vacaciones, no sé qué debería hacer.",
  ui_story_32270601_33_dialog_content = "Por el contrario, continuar realizando misiones brinda una sensación de comodidad y tranquilidad.",
  ui_story_32270601_34_dialog_content = "Si tan solo hubiera gatitos en la playa...",
  ui_story_32270601_35_dialog_content = "Eh... Si estamos de vacaciones, especialmente en la playa, en realidad hay muchas cosas que podemos hacer...",
  ui_story_32270601_36_dialog_content = "Hablando de eso, he tenido curiosidad por un tiempo, PlayerName, estás llevando una bolsa grande...",
  ui_story_32270601_37_dialog_content = "¿Es aquí donde se guarda el objeto de la misión?",
  ui_story_32270601_38_dialog_content = "Para decirlo con precisión... ¡Supongo que sí!",
  ui_story_32270601_39_dialog_content = "<color=#e8d9bb>¡Clink, clink!</color>",
  ui_story_32270601_40_dialog_content = "¿Pelota de entrenamiento físico, pistola de simulación de batalla y fruta hidratante para aliviar el calor?",
  ui_story_32270601_41_dialog_content = "Si especulamos basándonos en esto, la misión de PlayerName debería ser—",
  ui_story_32270601_42_dialog_content = "*Tose*... ¡Es vóleibol de playa, pistolas de agua y sandías!",
  ui_story_32270601_43_dialog_content = "Para ser precisos, ¡estos son todos los elementos esenciales para unas vacaciones en la playa!",
  ui_story_32270601_44_dialog_content = "Entonces, PlayerName, ¿habías decidido unirte a mí en las vacaciones de antemano?",
  ui_story_32270601_45_dialog_content = "Después de todo, es verano... la playa... no importa cómo lo pienses, tiene que ser unas vacaciones, ¿verdad!?",
  ui_story_32270601_46_dialog_content = "Eso es típico de ti, PlayerName. Si no fuera por ti, podría haber malinterpretado las intenciones del Gran Mariscal.",
  ui_story_32270601_47_dialog_content = "Basándonos en tu experiencia, ¿en qué actividad deberíamos participar ahora?",
  ui_story_32270601_48_option_content = "¿Qué tal si jugamos un poco de voleibol de playa?",
  ui_story_32270601_49_dialog_content = "Voleibol... Es un deporte con el que nunca me he encontrado antes.",
  ui_story_32270601_50_dialog_content = "Si eliges esto, me temo que tendrás que practicar conmigo, PlayerName.",
  ui_story_32270601_51_dialog_content = "Entonces, en realidad prefiero las pistolas de agua...",
  ui_story_32270601_52_option_content = "¿Qué tal si jugamos con pistolas de agua?",
  ui_story_32270601_53_dialog_content = "¿Pistola de agua? Es bastante similar al arma que he estado usando.",
  ui_story_32270601_54_dialog_content = "Incluso el efecto de silenciamiento está más allá de reproche.",
  ui_story_32270601_55_dialog_content = "Pero es un poco injusto para PlayerName...",
  ui_story_32270601_56_dialog_content = "Espera, espera, espera, espera, ¿realmente tenemos que competir?!",
  ui_story_32270601_57_dialog_content = "Por favor, asegúrate de ver este evento como una competencia.",
  ui_story_32270601_58_dialog_content = "Si tuviera que competir contra ti, PlayerName, podría aprender mucho.",
  ui_story_32270601_59_dialog_content = "(Siento que Rachel aún no se está soltando... ¿Es porque rara vez se toma un descanso...?)",
  ui_story_32270601_60_dialog_content = "(¡Realmente necesito hacerla sentir más involucrada!)",
  ui_story_32270601_61_dialog_content = "¡Entonces iré primero, esta pistola de agua premium de alta capacidad es mía!",
  ui_story_32270601_62_dialog_content = "Siéntete libre, PlayerName. Después de todo, cuando se trata de habilidades de tiro, estoy bastante seguro.",
  ui_story_32270601_63_dialog_content = "Hmph, jugar con pistolas de agua no requiere necesariamente habilidades de tiro, por ejemplo...",
  ui_story_32270601_64_dialog_content = "<color=#e8d9bb>Maricón-</color>",
  ui_story_32270601_65_dialog_content = "Está bien lanzar un ataque furtivo incluso si no es honorable.",
  ui_story_32270601_66_dialog_content = "...",
  ui_story_32270601_67_dialog_content = "Eh... ¿No deberíamos empezar a contraatacar en este punto?",
  ui_story_32270601_68_dialog_content = "Pero, apuntar con una pistola a PlayerName, es un poco...",
  ui_story_32270601_69_dialog_content = "Esta es una pistola de agua, Rachel.",
  ui_story_32270601_70_dialog_content = "¿Y no es esto lo que Rachel eligió? Fuiste tú quien sugirió la competencia, entonces...",
  ui_story_32270601_71_dialog_content = "<color=#e8d9bb>Silbido—Silbido—</color>",
  ui_story_32270601_72_dialog_content = "¡Así que incluso si no contraatacas, no me detendré!",
  ui_story_32270601_73_dialog_content = "¡Espera, espera!",
  ui_story_32270601_74_dialog_content = "¡No pararé hasta que Rachel admita la derrota!!",
  ui_story_32270601_75_dialog_content = "El perdedor perderá el derecho a distribuir sandías, ¡prepárate!",
  ui_story_32270601_76_dialog_content = "No me importa la sandía, pero ser el único empapado es bastante vergonzoso...",
  ui_story_32270601_77_dialog_content = "Estoy a punto de contraatacar, PlayerName.",
  ui_story_32270601_78_dialog_content = "<color=#e8d9bb>Siseo...</color>",
  ui_story_32270601_79_dialog_content = "Esta pistola ...",
  ui_story_32270601_80_dialog_content = "Se ve impresionante, pero ¿es su \"poder\" realmente tan bajo?",
  ui_story_32270601_81_dialog_content = "Necesito pensar en algo...",
  ui_story_32270601_82_dialog_content = "Jeje, entonces no me culpes... ¡Toma esto!",
  ui_story_32270601_83_dialog_content = "<color=#e8d9bb>Silbido—Silbido—</color>",
  ui_story_32270601_84_dialog_content = "Uh oh... Me han golpeado repetidamente...",
  ui_story_32270601_85_dialog_content = "Entonces, ¿PlayerName puede ser tan malicioso...?",
  ui_story_32270601_86_dialog_content = "Humph, parece que Rachel todavía no entiende la forma de sobrevivir en la playa!",
  ui_story_32270601_87_dialog_content = "¡Bueno, ya he ganado! ¡Soy la Leyenda de la Playa, el Rey de las Pistolas de Agua! Toma esto—",
  ui_story_32270601_88_dialog_content = "<color=#e8d9bb>Maricón-</color>",
  ui_story_32270601_89_dialog_content = "¿Eh... Por qué hay un escalofrío repentino en mi espalda?",
  ui_story_32270601_90_dialog_content = "PlayerName dijo que está bien incluso si no hablamos de ética marcial y emboscada, ¿verdad?",
  ui_story_32270601_91_dialog_content = "Parece que... podría haber dicho algo así, pero...",
  ui_story_32270601_92_dialog_content = "¿Cómo lograste dispararme por la espalda...?",
  ui_story_32270601_93_dialog_content = "<color=#e8d9bb>PlayerName se da la vuelta, encontrándose cara a cara con tres drones equipados con pistolas de agua.</color>",
  ui_story_32270601_94_dialog_content = "<color=#e8d9bb>Rodeándolo completamente, sin ningún punto ciego.</color>",
  ui_story_32270601_95_dialog_content = "Entonces, no dijiste que ella no podía pedir ayuda, ¿verdad?",
  ui_story_32270601_96_dialog_content = "Espera, espera, espera, si uso el Cazador de Águilas...",
  ui_story_32270601_97_dialog_content = "No te preocupes, todos los módulos de combate han sido desactivados. Ahora estamos en modo de enfoque de pistola de agua.",
  ui_story_32270601_98_dialog_content = "Acabas de decir \"Esto es solo una pistola de agua\", no es gran cosa.",
  ui_story_32270601_99_dialog_content = "¿Por qué... Por qué no puedo recordar haber pronunciado palabras tan irresponsables?",
  ui_story_32270601_100_dialog_content = "¡Golpe de garra!",
  ui_story_32270601_101_dialog_content = "<color=#e8d9bb>Silbido—<size=50>Silbido, silbido, silbido, silbido, silbido—!</size></color>",
  ui_story_32270601_102_dialog_content = "H-¡¡ayuda!!",
  ui_story_32270601_103_dialog_content = "<color=#e8d9bb>Finalmente, en medio de la persecución del dron y la risa alegre de Rachel...</color>",
  ui_story_32270601_104_dialog_content = "<color=#e8d9bb>\"El último Caelestite\", \"Rey de las Pistolas de Agua\", \"Leyenda de la Playa\" — PlayerName.</color>",
  ui_story_32270601_105_dialog_content = "<color=#e8d9bb>Dando la bienvenida a la derrota más brutal de este verano...</color>"
}
return config
